// Settings that belong to where the site is deployed, not to its code. The deploy overwrites this
// file (web/build.py) from the repository variables GOOGLE_API_KEY, which lets "Load from Google
// Drive" read files and folders shared as "Anyone with the link" (empty, the option is off), and
// DRIVE_DEFAULT_FOLDER, the link that option opens on.
window.NOR_CONFIG = {
  google: { apiKey: "" },
  drive: { defaultLink: "" },
};
// Drives the Google Drive dialog (web/) in headless Chromium against a stand-in Drive API that serves
// IMAGE... (lab images named in data/sources.json) and one image the lab's list lacks from a folder, with one
// subfolder holding the first image again: a click only selects a row, Open loads the selection, a double
// click enters a folder, and thumbnails come from the site's ready-made ones or one saved when an image was
// opened, never from Drive, and not at all while the remembered "Download thumbnails" is unticked.
// Prints what it measured; exits 1 when something is wrong, 2 when it cannot run. With SHOT, also saves a
// screenshot of the dialog there.
//   node tests/drive_dialog_driver.mjs SHOT|- IMAGE...
import { createRequire } from "node:module";
import { execSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import fs from "node:fs";
import http from "node:http";
import path from "node:path";

const require = createRequire(import.meta.url);
let pw;
try { pw = require("playwright"); } catch {
  try { pw = require(path.join(execSync("npm root -g").toString().trim(), "playwright")); } catch { console.error("no playwright: npm i -g playwright"); process.exit(2); }
}
const [shot, ...images] = process.argv.slice(2);
const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "..");

const ROOT = "rootfolder0000000001", SUB = "subfolder00000000001";
const lab = JSON.parse(fs.readFileSync(path.join(repo, "studies", "nor", "data", "sources.json"), "utf8")).sources.flatMap((x) => x.files || []);
const files = images.map((p) => {
  const known = lab.find((f) => p.endsWith(f.path));
  if (!known) { console.error(p + " is not in data/sources.json"); process.exit(2); }
  return { id: known.drive_id, name: path.basename(p), bytes: fs.readFileSync(p) };
});
const stranger = { id: "notinthelab000000001", name: "Not in the lab's list.tif", bytes: files[0].bytes };
const folders = {
  [ROOT]: [{ id: SUB, name: "More slides", mimeType: "application/vnd.google-apps.folder" }, ...[...files, stranger].map((f) => ({ ...f, mimeType: "image/tiff" }))],
  [SUB]: [{ ...files[0], mimeType: "image/tiff" }],
};
const CONFIG = `window.NOR_CONFIG = { google: { apiKey: "stand-in" }, drive: { defaultLink: "https://drive.google.com/drive/folders/${ROOT}" } };`;
const TYPES = { ".jpg": "image/jpeg", ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".json": "application/json", ".svg": "image/svg+xml", ".png": "image/png" };
let thumbsServed = 0;
const server = http.createServer((q, r) => {
  const u = decodeURIComponent(new URL(q.url, "http://x").pathname);
  if (u === "/web/worker.js") { r.writeHead(200, { "content-type": "text/javascript" }); return r.end(""); }
  if (u === "/web/config.js") { r.writeHead(200, { "content-type": "text/javascript" }); return r.end(CONFIG); }
  if (u.startsWith("/studies/nor/web/drive_thumbs/") && u.endsWith(".jpg")) thumbsServed++;
  const f = path.join(repo, u);
  if (!fs.existsSync(f) || fs.statSync(f).isDirectory()) { r.writeHead(404); return r.end(); }
  r.writeHead(200, { "content-type": TYPES[path.extname(f)] || "application/octet-stream" }); fs.createReadStream(f).pipe(r);
});
await new Promise((ok) => server.listen(0, "[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]", ok));
const origin = `http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:${server.address().port}`;

const browser = await pw.chromium.launch();
const done = async (code, why) => { if (why) console.error(why); await browser.close(); server.close(); process.exit(code); };
const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 } });
// what the page took from Drive: per file, how often the whole file and how often a piece of it
const asked = Object.fromEntries([...files, stranger].map((f) => [f.id, { whole: 0, pieces: 0 }]));
const cors = { "access-control-allow-origin": "*" };
await ctx.route("https://www.googleapis.com/**", (route) => {
  const q = route.request(), u = new URL(q.url());
  const m = u.pathname.match(/\/drive\/v3\/files\/?(.*)$/), id = m && m[1];
  if (!id) {
    const parent = u.searchParams.get("q").match(/'([\w-]+)' in parents/)[1];
    const list = (folders[parent] || []).map((f) => ({ id: f.id, name: f.name, mimeType: f.mimeType, size: f.bytes ? String(f.bytes.length) : undefined, createdTime: "2026-10-01T10:00:00Z" }));
    return route.fulfill({ status: 200, headers: cors, contentType: "application/json", body: JSON.stringify({ files: list }) });
  }
  const f = [...files, stranger].find((g) => g.id === id);
  if (!f) return route.fulfill({ status: 404, headers: cors, body: "{}" });
  if (q.headers()["range"]) { asked[id].pieces++; return route.fulfill({ status: 403, body: "refused" }); }
  asked[id].whole++;
  return route.fulfill({ status: 200, headers: cors, contentType: "image/tiff", body: f.bytes });
});
const fromDrive = () => Object.values(asked).reduce((n, a) => n + a.whole + a.pieces, 0);
await ctx.route((u) => !u.href.startsWith(origin) && !u.href.startsWith("https://www.googleapis.com/"), (r) => r.abort());
await ctx.addInitScript(() => { delete Navigator.prototype.serviceWorker; localStorage.setItem("nor-load-source", JSON.stringify("drive")); });
const page = await ctx.newPage();
"""R8: the Google Drive dialog selects on a click and opens on Open or a double click, and shows each lab
image's ready-made thumbnail (web/drive_thumbs.py, in this study) or the one saved when it was opened, never reading
Drive for one (drive_dialog_driver.mjs)."""
import glob, json, os, sys
from test_memory import HERE, TIF, needs_node, needs_slide, run
import pytest

pytestmark = pytest.mark.full

sys.path.insert(0, os.path.join(HERE, '..', 'web'))
import drive_thumbs


def test_every_lab_image_has_a_ready_made_thumbnail():
    """A file added to data/sources.json needs `python3 studies/nor/web/drive_thumbs.py` in the same change."""
    named = sorted(i for i, _ in drive_thumbs.images(json.load(open(os.path.join(HERE, '..', 'data', 'sources.json')))))
    assert json.load(open(os.path.join(drive_thumbs.OUT, 'index.json'))) == named
    assert sorted(os.path.basename(p)[:-4] for p in glob.glob(os.path.join(drive_thumbs.OUT, '*.jpg'))) == named


@needs_slide
@needs_node
def test_select_then_open_and_thumbnails_without_reading_drive():
    lab = [os.path.join(HERE, '..', 'data', 'raw', f['path']) for s in json.load(open(os.path.join(HERE, '..', 'data', 'sources.json')))['sources'] for f in s.get('files') or []]
    other = sorted(p for p in lab if os.path.exists(p) and not os.path.samefile(p, TIF))
    run('drive_dialog_driver.mjs', '-', TIF, *other[:1])

